-- Missing.lua : translations for texts that had no entry in any language (tooltips, HUD / Eagle Eye labels, skin names, messages).
-- Key = the English text used in the code. Loaded after Coverage.lua; a key already present in a language is kept as is.
local _, GT = ...
GT.locales = GT.locales or {}

local codes = { "deDE", "frFR", "itIT", "koKR", "jaJP", "ruRU", "zhCN", "ptBR", "esES", "idID", "suID" }
local rows = {
    { "Hide layer info (e.g. Layer 1) while the HUD is on", "Layer-Info (z. B. Layer 1) bei aktivem HUD ausblenden", "Masquer les infos de couche (ex. Layer 1) quand le HUD est activé", "Nascondi le info sul layer (es. Layer 1) con l'HUD attivo", "HUD가 켜져 있을 때 레이어 정보(예: Layer 1) 숨기기", "HUDがオンの間、レイヤー情報（例：Layer 1）を隠す", "Скрывать сведения о слое (например, Layer 1), когда HUD включён", "HUD 开启时隐藏位面信息（如 Layer 1）", "Ocultar informações de camada (ex.: Layer 1) com o HUD ligado", "Ocultar información de capa (p. ej., Layer 1) con el HUD activo", "Sembunyikan info layer (mis. Layer 1) saat HUD aktif", "Sumputkeun info layer (contona Layer 1) nalika HUD hurung" },
    { "On: the map turns so the direction you are facing is always up.", "An: Die Karte dreht sich so, dass deine Blickrichtung immer nach oben zeigt.", "Activé : la carte pivote pour que votre direction soit toujours vers le haut.", "Attivo: la mappa ruota per mantenere in alto la direzione verso cui guardi.", "켜짐: 바라보는 방향이 항상 위쪽이 되도록 지도가 회전합니다.", "オン：向いている方向が常に上になるようマップが回転します。", "Вкл.: карта поворачивается так, чтобы направление взгляда всегда было сверху.", "开启：地图旋转，使你面朝的方向始终朝上。", "Ativo: o mapa gira para que a direção para onde você olha fique sempre para cima.", "Activado: el mapa gira para que la dirección hacia la que miras quede siempre arriba.", "Aktif: peta berputar agar arah hadapmu selalu di atas.", "Hurung: peta muter supaya arah nu disanghareupan salawasna di luhur." },
    { "On: an arrow in the middle of the map shows which way you are facing. It is hidden while the Eagle map is up.", "An: Ein Pfeil in der Kartenmitte zeigt deine Blickrichtung. Bei geöffneter Adlerkarte wird er ausgeblendet.", "Activé : une flèche au centre de la carte indique votre direction. Elle est masquée quand la carte Œil d'aigle est affichée.", "Attivo: una freccia al centro della mappa indica la direzione. È nascosta quando è aperta la mappa Occhio d'aquila.", "켜짐: 지도 중앙의 화살표가 바라보는 방향을 표시합니다. 독수리의 눈 지도가 표시되면 숨겨집니다.", "オン：マップ中央の矢印で向いている方向を示します。イーグルアイのマップ表示中は隠れます。", "Вкл.: стрелка в центре карты показывает направление взгляда. При открытой карте Орлиного взора она скрыта.", "开启：地图中央的箭头显示你面朝的方向。鹰眼地图显示时会隐藏。", "Ativo: uma seta no centro do mapa indica para onde você está virado. Ela fica oculta com o mapa Olho de Águia aberto.", "Activado: una flecha en el centro indica hacia dónde miras. Se oculta mientras se muestra el mapa Ojo de águila.", "Aktif: panah di tengah peta menunjukkan arah hadapmu. Tersembunyi saat peta Eagle tampil.", "Hurung: panah di tengah peta némbongkeun arah nyanghareup. Disumputkeun nalika peta Eagle muka." },
    { "On: the HUD hides while you are mounted and comes back when you dismount.", "An: Das HUD wird beim Reiten ausgeblendet und erscheint nach dem Absteigen wieder.", "Activé : le HUD se masque à monture et réapparaît après être descendu.", "Attivo: l'HUD si nasconde in sella e ricompare quando smonti.", "켜짐: 탈것에 타면 HUD가 숨겨지고 내리면 다시 나타납니다.", "オン：騎乗中はHUDが隠れ、降りると再表示されます。", "Вкл.: HUD скрывается верхом и появляется после спешивания.", "开启：骑乘时隐藏 HUD，下马后重新显示。", "Ativo: o HUD desaparece enquanto você está montado e volta ao desmontar.", "Activado: el HUD se oculta al montar y vuelve al desmontar.", "Aktif: HUD disembunyikan saat berkendara dan muncul lagi setelah turun.", "Hurung: HUD disumputkeun nalika naék, tuluy némbongan deui sanggeus turun." },
    { "On: the HUD turns on by itself while a gathering tracking spell is active (Find Herbs, Find Minerals, Find Treasure), and turns off again afterwards.", "An: Das HUD schaltet sich bei aktiver Sammelverfolgung (Kräuter, Mineralien oder Schätze finden) automatisch ein und danach wieder aus.", "Activé : le HUD s'active pendant un sort de pistage (herbes, minerais ou trésors), puis se désactive.", "Attivo: l'HUD si accende con un incantesimo di tracciamento (erbe, minerali o tesori) e poi si spegne.", "켜짐: 약초·광물·보물 찾기 추적 주문이 활성화되면 HUD가 켜지고 이후 꺼집니다.", "オン：ハーブ・鉱物・財宝探知中にHUDが自動でオンになり、その後オフになります。", "Вкл.: HUD включается при поиске трав, руды или сокровищ и выключается после.", "开启：采药、探矿或寻宝追踪生效时自动开启 HUD，结束后关闭。", "Ativo: o HUD liga durante o rastreamento de ervas, minérios ou tesouros e desliga depois.", "Activado: el HUD se enciende al rastrear hierbas, minerales o tesoros y se apaga al terminar.", "Aktif: HUD menyala saat pelacakan Herbal, Mineral, atau Harta aktif, lalu mati.", "Hurung: HUD hurung nalika ngalacak Herbal, Mineral, atawa Harta, tuluy pareum deui." },
    { "On: the HUD turns off in resting areas such as cities, towns and inns.", "An: Das HUD wird in Ruhegebieten wie Städten und Gasthäusern ausgeschaltet.", "Activé : le HUD se désactive dans les zones de repos comme les villes et auberges.", "Attivo: l'HUD si spegne nelle zone di riposo come città e locande.", "켜짐: 도시, 마을, 여관 같은 휴식 지역에서 HUD가 꺼집니다.", "オン：街や宿屋などの休息エリアでHUDがオフになります。", "Вкл.: HUD выключается в зонах отдыха, например в городах и тавернах.", "开启：在城市、城镇和旅店等休息区域关闭 HUD。", "Ativo: o HUD desliga em áreas de descanso, como cidades e estalagens.", "Activado: el HUD se apaga en zonas de descanso, como ciudades y posadas.", "Aktif: HUD mati di area istirahat seperti kota dan penginapan.", "Hurung: HUD pareum di wewengkon reureuh saperti kota jeung panginepan." },
    { "On: the Gx labels and (G) timers on the minimap are hidden while the HUD is off.", "An: Gx-Beschriftungen und (G)-Timer auf der Minikarte werden bei ausgeschaltetem HUD ausgeblendet.", "Activé : les étiquettes Gx et minuteurs (G) de la minicarte sont masqués quand le HUD est désactivé.", "Attivo: etichette Gx e timer (G) sulla minimappa vengono nascosti quando l'HUD è spento.", "켜짐: HUD가 꺼져 있을 때 미니맵의 Gx 표시와 (G) 타이머를 숨깁니다.", "オン：HUDがオフの間、ミニマップのGxラベルと(G)タイマーを隠します。", "Вкл.: при выключенном HUD скрываются метки Gx и таймеры (G) на миникарте.", "开启：HUD 关闭时隐藏小地图上的 Gx 标签和 (G) 计时。", "Ativo: oculta rótulos Gx e temporizadores (G) do minimapa enquanto o HUD está desligado.", "Activado: oculta las etiquetas Gx y los temporizadores (G) del minimapa mientras el HUD está apagado.", "Aktif: sembunyikan label Gx dan timer (G) di minimap saat HUD mati.", "Hurung: sumputkeun label Gx jeung timer (G) dina minimap nalika HUD pareum." },
    { "On: the layer label (such as Layer 1) on the minimap is hidden while the HUD or the Eagle map is on, and comes back when they are off.", "An: Die Layer-Anzeige (z. B. Layer 1) auf der Minikarte wird bei aktivem HUD oder Adlerkarte ausgeblendet und danach wieder angezeigt.", "Activé : l'indication de couche (comme Layer 1) est masquée sur la minicarte quand le HUD ou la carte Œil d'aigle est actif, puis réapparaît.", "Attivo: l'etichetta del layer (es. Layer 1) è nascosta sulla minimappa con l'HUD o la mappa Occhio d'aquila attivi, poi ricompare.", "켜짐: HUD 또는 독수리의 눈 지도가 켜져 있을 때 미니맵의 레이어 표시(예: Layer 1)를 숨기고 이후 복원합니다.", "オン：HUDまたはイーグルアイのマップ表示中はミニマップのレイヤー表示（Layer 1など）を隠し、終了後に戻します。", "Вкл.: метка слоя (например, Layer 1) скрывается на миникарте при включённом HUD или карте Орлиного взора и возвращается после.", "开启：HUD 或鹰眼地图开启时隐藏小地图上的位面标签（如 Layer 1），关闭后恢复。", "Ativo: oculta a indicação de camada (como Layer 1) no minimapa enquanto o HUD ou o mapa Olho de Águia está ativo.", "Activado: oculta la etiqueta de capa (como Layer 1) del minimapa mientras el HUD o el mapa Ojo de águila está activo.", "Aktif: sembunyikan label layer (seperti Layer 1) di minimap saat HUD atau peta Eagle aktif.", "Hurung: sumputkeun label layer (saperti Layer 1) dina minimap nalika HUD atawa peta Eagle hurung." },
    { "On: the map is drawn smaller (75%) with no rings, no compass letters and no heading readout. Turn it off to bring them back; your saved values are kept.", "An: Die Karte wird kleiner (75 %) ohne Ringe, Kompassbuchstaben und Richtungsanzeige dargestellt. Ausgeschaltet kehren sie zurück; gespeicherte Werte bleiben erhalten.", "Activé : la carte est réduite (75 %), sans anneaux, lettres de boussole ni cap. Désactivez pour les retrouver ; vos valeurs restent enregistrées.", "Attivo: la mappa è più piccola (75%), senza anelli, lettere della bussola o direzione. Disattiva per ripristinarli; i valori restano salvati.", "켜짐: 지도를 75%로 줄이고 링, 나침반 문자, 방향 표시를 숨깁니다. 끄면 복원되며 저장된 값은 유지됩니다.", "オン：マップを75%に縮小し、リング・方位文字・方向表示を隠します。オフにすると戻り、保存値は保持されます。", "Вкл.: карта уменьшается до 75%, кольца, буквы компаса и направление скрываются. Выключите, чтобы вернуть; сохранённые значения сохраняются.", "开启：地图缩小至 75%，并隐藏圆环、罗盘字母和方向读数。关闭后恢复，已保存数值保留。", "Ativo: reduz o mapa para 75%, sem anéis, letras da bússola ou direção. Desative para restaurá-los; os valores salvos são mantidos.", "Activado: reduce el mapa al 75 % y oculta anillos, letras de brújula y rumbo. Desactívalo para recuperarlos; se conservan los valores.", "Aktif: peta menjadi 75%, tanpa cincin, huruf kompas, atau arah. Matikan untuk mengembalikannya; nilai tersimpan tetap.", "Hurung: peta jadi 75%, tanpa cingcin, hurup kompas, jeung arah. Pareuman pikeun mulangkeunana; nilai tetep." },
    { "On: the buttons and borders that other addons put around the minimap (SexyMap, ElvUI, LibDBIcon and similar) are hidden while the HUD is on.", "An: Schaltflächen und Rahmen anderer Addons um die Minikarte (SexyMap, ElvUI, LibDBIcon usw.) werden bei aktivem HUD ausgeblendet.", "Activé : les boutons et bordures ajoutés autour de la minicarte par d'autres addons (SexyMap, ElvUI, LibDBIcon...) sont masqués.", "Attivo: pulsanti e bordi aggiunti da altri addon attorno alla minimappa (SexyMap, ElvUI, LibDBIcon...) vengono nascosti.", "켜짐: HUD가 켜져 있을 때 다른 애드온이 미니맵 주변에 추가한 버튼과 테두리(SexyMap, ElvUI, LibDBIcon 등)를 숨깁니다.", "オン：HUDが有効な間、他のアドオン（SexyMap、ElvUI、LibDBIconなど）がミニマップ周辺に追加したボタンや枠を隠します。", "Вкл.: при активном HUD скрываются кнопки и рамки вокруг миникарты от других аддонов (SexyMap, ElvUI, LibDBIcon и т. п.).", "开启：HUD 启用时隐藏其他插件添加在小地图周围的按钮和边框（SexyMap、ElvUI、LibDBIcon 等）。", "Ativo: oculta botões e bordas que outros addons colocam ao redor do minimapa (SexyMap, ElvUI, LibDBIcon e similares).", "Activado: oculta los botones y bordes que otros addons ponen alrededor del minimapa (SexyMap, ElvUI, LibDBIcon y similares).", "Aktif: sembunyikan tombol dan bingkai addon lain di sekitar minimap (SexyMap, ElvUI, LibDBIcon, dll.).", "Hurung: sumputkeun tombol jeung wates addon séjén di sabudeureun minimap (SexyMap, ElvUI, LibDBIcon, jsb.)." },
    { "On: the HUD prints its debug messages in chat. Only useful when reporting a problem.", "An: Das HUD gibt Debugmeldungen im Chat aus. Nur beim Melden eines Problems nützlich.", "Activé : le HUD affiche ses messages de débogage dans le chat. Utile uniquement pour signaler un problème.", "Attivo: l'HUD stampa messaggi di debug in chat. Utile solo per segnalare un problema.", "켜짐: HUD 디버그 메시지를 채팅에 출력합니다. 문제를 보고할 때만 유용합니다.", "オン：HUDのデバッグメッセージをチャットに表示します。問題報告時のみ有用です。", "Вкл.: HUD выводит отладочные сообщения в чат. Полезно только при сообщении о проблеме.", "开启：HUD 在聊天中输出调试消息。仅在报告问题时有用。", "Ativo: o HUD envia mensagens de depuração no chat. Útil apenas ao relatar um problema.", "Activado: el HUD muestra mensajes de depuración en el chat. Solo es útil al informar de un problema.", "Aktif: HUD mencetak pesan debug di chat. Berguna hanya saat melaporkan masalah.", "Hurung: HUD mintonkeun pesen debug dina chat. Mangpaat ngan nalika ngalaporkeun masalah." },
    { "On: if the HUD is on at Full and the frame rate stays under 25 FPS for 30 seconds, one chat line points you to this tab. It is shown once.", "An: Wenn das HUD auf Voll läuft und die Bildrate 30 Sekunden unter 25 FPS bleibt, weist eine Chatzeile einmalig auf diesen Tab hin.", "Activé : si le HUD est en mode Complet et reste sous 25 FPS pendant 30 secondes, une ligne de chat indique cet onglet une seule fois.", "Attivo: se l'HUD è su Completo e il frame rate resta sotto 25 FPS per 30 secondi, un messaggio indica questa scheda una sola volta.", "켜짐: HUD가 전체 모드일 때 30초 동안 25 FPS 미만이면 채팅으로 이 탭을 한 번 안내합니다.", "オン：HUDがフルで30秒間25 FPS未満の場合、このタブを案内するチャット表示を一度だけ行います。", "Вкл.: если HUD работает на полном уровне и частота кадров ниже 25 FPS 30 секунд, чат один раз предложит эту вкладку.", "开启：HUD 处于完整模式且帧率连续 30 秒低于 25 FPS 时，聊天中会提示此标签页一次。", "Ativo: se o HUD estiver em Completo e ficar abaixo de 25 FPS por 30 segundos, uma mensagem indicará esta aba uma vez.", "Activado: si el HUD está en Completo y los FPS permanecen bajo 25 durante 30 segundos, el chat indicará esta pestaña una sola vez.", "Aktif: jika HUD pada mode Penuh dan FPS di bawah 25 selama 30 detik, satu pesan chat menyarankan tab ini.", "Hurung: lamun HUD mode Pinuh jeung FPS handapeun 25 salila 30 detik, hiji pesen chat nuduhkeun tab ieu." },
    { "On: the HUD also searches the other frames on screen for minimap addons it does not know by name. This uses more processing, so keep it off unless a minimap addon is not being hidden. It is always off in Balanced and Lowest (minimap skin addons the HUD knows by name, such as SexyMap, are still handled).", "An: Das HUD durchsucht andere sichtbare Frames nach unbekannten Minimap-Addons. Das kostet Leistung; nur einschalten, wenn ein Addon nicht ausgeblendet wird. In Ausgewogen und Niedrig immer aus; bekannte Skins wie SexyMap werden weiter behandelt.", "Activé : le HUD recherche aussi les cadres visibles pour repérer les addons de minicarte inconnus. Cela consomme plus de ressources ; laissez désactivé sauf si un addon n'est pas masqué. Toujours désactivé en Équilibré et Bas ; les skins connus comme SexyMap restent gérés.", "Attivo: l'HUD cerca negli altri riquadri gli addon minimappa sconosciuti. Richiede più risorse; lascialo disattivato salvo problemi di occultamento. Sempre disattivo in Bilanciato e Minimo; gli addon noti come SexyMap restano gestiti.", "켜짐: HUD가 화면의 다른 프레임도 검색해 알 수 없는 미니맵 애드온을 찾습니다. 처리 부하가 늘어나므로 숨겨지지 않는 애드온이 있을 때만 켜세요. 균형·최저 모드에서는 항상 꺼지며 SexyMap 같은 알려진 스킨은 계속 처리됩니다.", "オン：HUDが画面上の他のフレームも検索し、未認識のミニマップアドオンを探します。負荷が増えるため、非表示にならないアドオンがある場合のみ有効にしてください。バランス・最低では常にオフですが、SexyMapなど認識済みのスキンは処理されます。", "Вкл.: HUD ищет неизвестные аддоны миникарты в других видимых фреймах. Это требует ресурсов; включайте, только если аддон не скрывается. В режимах «Сбалансированный» и «Минимальный» выключено; известные скины вроде SexyMap обрабатываются.", "开启：HUD 还会搜索屏幕上的其他框架，以查找无法识别的小地图插件。这会增加开销，只有插件未被隐藏时才建议开启。平衡和最低模式下始终关闭（仍会处理 SexyMap 等已知皮肤）。", "Ativo: o HUD procura em outros quadros addons de minimapa que não reconhece. Isso exige mais processamento; deixe desligado, a menos que algum addon não esteja oculto. Fica sempre desligado em Equilibrado e Mínimo; skins conhecidas como SexyMap continuam sendo tratadas.", "Activado: el HUD busca en otros marcos addons de minimapa que no reconoce. Consume más recursos; déjalo apagado salvo que alguno no se oculte. Siempre está desactivado en Equilibrado y Mínimo; se siguen gestionando skins conocidas como SexyMap.", "Aktif: HUD mencari addon minimap yang tidak dikenal pada frame lain. Ini memakai lebih banyak pemrosesan; biarkan mati kecuali ada addon yang tidak tersembunyi. Selalu mati pada mode Seimbang dan Terendah; skin dikenal seperti SexyMap tetap ditangani.", "Hurung: HUD néangan addon minimap nu teu dipikawanoh dina frame séjén. Ieu merlukeun pamrosésan leuwih; antep pareum iwal aya addon nu teu kasumputkeun. Pareum dina mode Saimbang jeung Panghandapna; skin nu dipikawanoh saperti SexyMap tetep diurus." },
    { "Buffs level with the bar", "Stärkungen auf Höhe der Leiste", "Aligner les buffs sur la barre", "Allinea i potenziamenti alla barra", "버프를 바와 같은 높이에 표시", "バフをバーと同じ高さに配置", "Баффы на уровне панели", "增益效果与栏对齐", "Buffs alinhados à barra", "Alinear beneficios con la barra", "Buff sejajar dengan bilah", "Buff sajajar jeung bar" },
    { "On: the buff icons stay on the same line as the player frame and the fps / ping line, even when the line is wide. Off: they drop lower when the line would cover them.", "An: Stärkungssymbole bleiben auch bei breiter Leiste auf einer Höhe mit Spielerfenster und FPS-/Ping-Zeile. Aus: Sie rutschen nach unten, wenn die Zeile sie überdecken würde.", "Activé : les icônes de buffs restent sur la ligne du cadre du joueur et des FPS/pings, même si elle est large. Désactivé : elles descendent si la ligne les recouvre.", "Attivo: le icone dei potenziamenti restano sulla riga del riquadro del personaggio e FPS/ping, anche se larga. Disattivo: scendono se la riga le copre.", "켜짐: 버프 아이콘을 플레이어 프레임 및 FPS/핑 줄과 같은 줄에 유지합니다. 꺼짐: 줄이 아이콘을 가리면 아래로 내립니다.", "オン：バフアイコンをプレイヤーフレームやFPS/ ping行と同じ行に保ちます。オフ：重なる場合は下に移動します。", "Вкл.: значки эффектов остаются на линии с окном персонажа и FPS/пингом. Выкл.: они смещаются ниже, если строка перекрывает их.", "开启：增益图标与玩家框架及 FPS/延迟行保持同一行。关闭：如果该行会遮挡图标，则将其下移。", "Ativo: os ícones de buffs ficam na linha do quadro do jogador e FPS/ping. Desativado: descem se a linha os cobrir.", "Activado: los iconos quedan en la línea del marco del jugador y FPS/ping. Desactivado: bajan si la línea los tapa.", "Aktif: ikon buff sejajar dengan frame pemain dan baris FPS/ping. Mati: ikon turun jika baris menutupinya.", "Hurung: ikon buff sajajar jeung frame pamaén jeung garis FPS/ping. Pareum: ikon turun lamun katutup ku garis." },
    { "Top offset: %s", "Oberer Abstand: %s", "Décalage supérieur : %s", "Offset superiore: %s", "상단 간격: %s", "上端オフセット：%s", "Отступ сверху: %s", "顶部偏移：%s", "Deslocamento superior: %s", "Desplazamiento superior: %s", "Jarak atas: %s", "Jarak luhur: %s" },
    { "How far the minimized bar sits below the top edge of the screen. Raise it to clear Titan Panel or another bar at the top; the game frames move down with it.", "Abstand der minimierten Leiste zum oberen Bildschirmrand. Erhöhe ihn, um Titan Panel oder andere obere Leisten freizuhalten; Spielframes werden mit verschoben.", "Distance entre la barre réduite et le haut de l'écran. Augmentez-la pour éviter Titan Panel ou une autre barre ; les cadres du jeu descendent aussi.", "Distanza della barra minimizzata dal bordo superiore. Aumentala per evitare Titan Panel o altre barre; anche i riquadri di gioco si spostano.", "최소화 바와 화면 위쪽 가장자리 사이의 거리입니다. Titan Panel 등 상단 바를 피하도록 높이면 게임 프레임도 함께 내려갑니다.", "最小化バーと画面上端の間隔です。Titan Panelなどを避けるために増やすと、ゲームフレームも下がります。", "Расстояние панели от верхнего края. Увеличьте, чтобы обойти Titan Panel или другую панель; игровые окна тоже сдвинутся вниз.", "最小化栏距屏幕顶部的距离。增大可避开 Titan Panel 等顶部栏；游戏框架也会下移。", "Distância da barra minimizada até o topo. Aumente para liberar espaço para Titan Panel ou outra barra; os quadros do jogo também descem.", "Distancia entre la barra minimizada y el borde superior. Auméntala para dejar espacio a Titan Panel u otra barra; los marcos también bajan.", "Jarak bilah mini dari tepi atas. Tambah untuk menghindari Titan Panel atau bilah lain; frame game ikut turun.", "Jarak bar mini ti sisi luhur. Tambahkeun pikeun nyingkahan Titan Panel atawa bar séjén; frame game ogé turun." },
    { "Show game time", "Spielzeit anzeigen", "Afficher l'heure du jeu", "Mostra ora di gioco", "게임 시간 표시", "ゲーム時間を表示", "Показывать игровое время", "显示游戏时间", "Mostrar hora do jogo", "Mostrar hora del juego", "Tampilkan waktu game", "Tembongkeun waktu game" },
    { "On: the fps / ping line also shows the game (server) time, e.g. game 14:05.", "An: Die FPS-/Ping-Zeile zeigt zusätzlich die Spielzeit (Serverzeit), z. B. game 14:05.", "Activé : la ligne FPS/ping affiche aussi l'heure du jeu (serveur), ex. game 14:05.", "Attivo: la riga FPS/ping mostra anche l'ora di gioco (server), es. game 14:05.", "켜짐: FPS/핑 줄에 게임(서버) 시간도 표시합니다(예: game 14:05).", "オン：FPS/ ping行にゲーム（サーバー）時刻も表示します（例：game 14:05）。", "Вкл.: строка FPS/пинга показывает игровое (серверное) время, например game 14:05.", "开启：FPS/延迟行还会显示游戏（服务器）时间，例如 game 14:05。", "Ativo: a linha FPS/ping também mostra a hora do jogo (servidor), ex.: game 14:05.", "Activado: la línea FPS/ping también muestra la hora del juego (servidor), p. ej., game 14:05.", "Aktif: baris FPS/ping juga menampilkan waktu game (server), mis. game 14:05.", "Hurung: garis FPS/ping ogé mintonkeun waktu game (server), contona game 14:05." },
    { "Show local time", "Lokale Zeit anzeigen", "Afficher l'heure locale", "Mostra ora locale", "현지 시간 표시", "ローカル時刻を表示", "Показывать местное время", "显示本地时间", "Mostrar hora local", "Mostrar hora local", "Tampilkan waktu lokal", "Tembongkeun waktu lokal" },
    { "On: the fps / ping line also shows your computer's time, e.g. local 21:05.", "An: Die FPS-/Ping-Zeile zeigt zusätzlich die Uhrzeit deines Computers, z. B. local 21:05.", "Activé : la ligne FPS/ping affiche aussi l'heure de votre ordinateur, ex. local 21:05.", "Attivo: la riga FPS/ping mostra anche l'ora del computer, es. local 21:05.", "켜짐: FPS/핑 줄에 컴퓨터 시간도 표시합니다(예: local 21:05).", "オン：FPS/ ping行にパソコンの時刻も表示します（例：local 21:05）。", "Вкл.: строка FPS/пинга показывает время компьютера, например local 21:05.", "开启：FPS/延迟行还会显示电脑时间，例如 local 21:05。", "Ativo: a linha FPS/ping também mostra a hora do computador, ex.: local 21:05.", "Activado: la línea FPS/ping también muestra la hora de tu ordenador, p. ej., local 21:05.", "Aktif: baris FPS/ping juga menampilkan waktu komputer, mis. local 21:05.", "Hurung: garis FPS/ping ogé mintonkeun waktu komputer, contona local 21:05." },
    { "Import GatherMate2 automatically on zone change", "GatherMate2 beim Zonenwechsel automatisch importieren", "Importer GatherMate2 automatiquement au changement de zone", "Importa GatherMate2 automaticamente al cambio di zona", "지역 변경 시 GatherMate2 자동 가져오기", "ゾーン変更時にGatherMate2を自動インポート", "Автоматически импортировать GatherMate2 при смене зоны", "切换区域时自动导入 GatherMate2", "Importar GatherMate2 automaticamente ao mudar de zona", "Importar GatherMate2 automáticamente al cambiar de zona", "Impor GatherMate2 otomatis saat pindah zona", "Impor GatherMate2 otomatis nalika pindah zona" },
    { "On: when you enter a zone, its GatherMate2 data is imported by itself (once per zone and session, quietly). Off: only the Import GatherMate2 button imports.", "An: Beim Betreten einer Zone werden deren GatherMate2-Daten automatisch importiert (einmal pro Zone und Sitzung, ohne Meldung). Aus: Nur die Import-Schaltfläche importiert.", "Activé : les données GatherMate2 sont importées à l'entrée de zone (une fois par zone et session, sans message). Désactivé : seul le bouton d'import agit.", "Attivo: entrando in una zona, i dati GatherMate2 vengono importati (una volta per zona e sessione, senza messaggi). Disattivo: importa solo il pulsante.", "켜짐: 지역에 들어가면 GatherMate2 데이터를 지역 및 세션당 한 번 조용히 자동 가져옵니다. 꺼짐: 가져오기 버튼으로만 가져옵니다.", "オン：ゾーンに入るとGatherMate2データをゾーン・セッションごとに一度、自動かつ通知なしで取り込みます。オフ：ボタンでのみ取り込みます。", "Вкл.: при входе в зону её данные GatherMate2 импортируются один раз за зону и сессию без сообщений. Выкл.: импорт только кнопкой.", "开启：进入区域时自动静默导入该区域的 GatherMate2 数据（每个区域、每次会话一次）。关闭：仅通过按钮导入。", "Ativo: ao entrar em uma zona, seus dados GatherMate2 são importados uma vez por zona e sessão, sem aviso. Desativado: só o botão importa.", "Activado: al entrar en una zona, sus datos se importan una vez por zona y sesión, sin avisos. Desactivado: solo importa el botón.", "Aktif: saat memasuki zona, data GatherMate2 diimpor sekali per zona dan sesi tanpa pesan. Mati: hanya tombol impor yang menjalankan impor.", "Hurung: nalika asup zona, data GatherMate2 diimpor sakali per zona jeung sési tanpa béwara. Pareum: ngan tombol impor nu ngimpor." },
    { "On: a small pop-up on the right of the screen when a guild member or a friend comes online (gold, with a sound) or goes offline (red, with a sound). When available, it also shows their level, class, guild and location. It hides by itself after the time on the button next to it. Clicking that button shows a demo.", "An: Eine Meldung erscheint rechts, wenn Gildenmitglieder oder Freunde online (gold, mit Ton) oder offline (rot, mit Ton) gehen. Falls verfügbar, zeigt sie Stufe, Klasse, Gilde und Ort. Sie verschwindet nach der Dauer der Schaltfläche daneben; ein Klick zeigt eine Vorschau.", "Activé : une fenêtre apparaît à droite lorsqu'un membre de guilde ou un ami se connecte (or, avec un son) ou se déconnecte (rouge, avec un son). Si disponibles, niveau, classe, guilde et lieu sont affichés. Elle disparaît après la durée du bouton voisin ; cliquer sur celui-ci montre une démo.", "Attivo: appare un avviso a destra quando un amico o membro della gilda entra (oro, con suono) o esce (rosso, con suono). Se disponibili mostra livello, classe, gilda e posizione. Scompare dopo il tempo del pulsante accanto; quel pulsante mostra una demo.", "켜짐: 길드원이나 친구가 접속하면 금색(소리 포함), 로그아웃하면 빨간색(소리 포함) 알림이 오른쪽에 표시됩니다. 가능하면 레벨, 직업, 길드, 위치도 표시합니다. 옆 버튼의 시간 후 사라지며 버튼을 클릭하면 미리보기가 나옵니다.", "オン：ギルドメンバーやフレンドのログイン時（ゴールド、音あり）またはログアウト時（赤、音あり）に画面右側へ通知します。可能な場合はレベル、クラス、ギルド、場所も表示します。隣のボタンで設定した時間後に消え、クリックするとデモを表示します。", "Вкл.: справа появляется уведомление о входе друга или участника гильдии (золотое, со звуком) или выходе (красное, со звуком). При наличии данных показываются уровень, класс, гильдия и место. Оно исчезает через время соседней кнопки; кнопка показывает демо.", "开启：公会成员或好友上线时显示金色通知（带声音），下线时显示红色通知（带声音）。可用时还显示等级、职业、公会和位置。通知会在旁边按钮设定的时间后隐藏；点击按钮可预览。", "Ativo: um aviso aparece à direita quando um amigo ou membro da guilda fica online (dourado, com som) ou offline (vermelho, com som). Quando disponíveis, mostra nível, classe, guilda e local. Some após o tempo do botão ao lado; clicar nele mostra uma demonstração.", "Activado: aparece un aviso a la derecha cuando un miembro de hermandad o amigo se conecta (dorado, con sonido) o desconecta (rojo, con sonido). Si están disponibles, muestra nivel, clase, hermandad y ubicación. Desaparece tras el tiempo del botón contiguo; al pulsarlo muestra una demostración.", "Aktif: pop-up muncul di kanan saat anggota guild atau teman online (emas, bersuara) atau offline (merah, bersuara). Jika tersedia, tampilkan level, kelas, guild, dan lokasi. Pop-up hilang setelah waktu tombol sebelahnya; klik tombol itu untuk demo.", "Hurung: béwara muncul di katuhu nalika anggota guild atawa babaturan online (emas, aya sora) atawa offline (beureum, aya sora). Lamun aya, mintonkeun tingkat, kelas, guild, jeung lokasi. Béwara leungit sanggeus waktu dina tombol gigireunna; klik tombol éta pikeun démo." },
